/**
 * ETag Support
 *
 * Compute a weak ETag from a JSON body string.
 * Uses Web Crypto API (available in Cloudflare Workers + Node 18+).
 */
async function computeEtag(body: string): Promise<string> {
  const data = new TextEncoder().encode(body);
  const hash = await crypto.subtle.digest('SHA-256', data);
  const hex = [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, '0')).join('').slice(0, 16);
  return 'W/"' + hex + '"';
}

/**
 * Return a JSON response with ETag support.
 * If the client sends a matching If-None-Match header, returns 304 Not Modified.
 */
export async function jsonWithEtag(c: any, data: any): Promise<Response> {
  const body = JSON.stringify(data);
  const etag = await computeEtag(body);

  const ifNoneMatch = c.req.header('If-None-Match');
  if (ifNoneMatch === etag) {
    return new Response(null, { status: 304, headers: { 'ETag': etag } });
  }

  return new Response(body, {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
      'ETag': etag,
      'Cache-Control': 'private, no-cache',
    },
  });
}

/**
 * SHA-1 hex digest of a string (Web Crypto). The bundle-etag primitive —
 * use for cache-seed etags on aggregate reads.
 */
export async function sha1Hex(body: string): Promise<string> {
  const data = new TextEncoder().encode(body);
  const hash = await crypto.subtle.digest('SHA-1', data);
  return [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, '0')).join('');
}

/** Response representation. v1 emits one format. */
export type RenderFormat = 'flat';

/** Content negotiation — the seam where a second representation would branch. v1: flat only. */
export function pickFormat(_c: any): RenderFormat {
  return 'flat';
}

/**
 * Render a single resource. The flat representation IS the resource object;
 * a future representation branches here without touching any route.
 * `extras.included` (`?include=`) merges the top-level
 * included map alongside the resource fields.
 */
export function renderResource(c: any, resource: any, extras?: { included?: any }) {
  return jsonWithEtag(c, extras?.included !== undefined ? { ...resource, included: extras.included } : resource);
}

/**
 * Render a collection. The flat envelope is { data, view?, pagination?,
 * aggregations?, included? }. The pagination shape (offset today, cursor
 * next) lives here, in one place — so Piece 3 changes it once, not per
 * route. `included` is the `?include=` compound block:
 * a map keyed by FK column, then by target PK.
 */
export function renderCollection(
  c: any,
  payload: { data?: any; view?: any; pagination?: any; aggregations?: any; included?: any },
) {
  const body: Record<string, unknown> = {};
  if (payload.data !== undefined) body.data = payload.data;
  if (payload.view !== undefined) body.view = payload.view;
  if (payload.pagination !== undefined) body.pagination = payload.pagination;
  if (payload.aggregations !== undefined) body.aggregations = payload.aggregations;
  if (payload.included !== undefined) body.included = payload.included;
  return jsonWithEtag(c, body);
}

